      <div class="info-row"><span class="ir-label">Monthly Revenue</span><span class="ir-value pos">${fmt$(revenueMonthly)}</span></div>
      <div class="info-row"><span class="ir-label">Customer Sentiment</span><span class="ir-value" style="color:${sentColor}">${sentiment}% ${sentiment>=75?'ðŸ˜Š':sentiment>=55?'ðŸ˜�':'ðŸ˜ '}</span></div>
      <div class="info-row"><span class="ir-label">Workplace Efficiency</span><span class="ir-value" style="color:${effColor}">${efficiency}% ${efficiency>=75?'âš¡':efficiency>=55?'âš™ï¸�':'ðŸ�¢'}</span></div>
      <div class="info-row"><span class="ir-label">Order Fulfillment</span><span class="ir-value" style="color:${effColor}">${Math.round(efficiency*0.95)}%</span></div>
